const parts = msg.topic.split('/');
if (parts.length < 4) {
    return null;
}
const device = parts[2];
const metric = parts.slice(3).join('/');
let state = flow.get('deviceState') || {};
const entry = state[device] || {
    device,
    temp: null,
    humidity: null,
    mq2raw: null,
    mq2voltage: null,
    flame: null,
    gpsStatus: null,
    latitude: null,
    longitude: null,
    updated: null
};
const value = msg.payload.toString();
switch (metric) {
    case 'temp':
        entry.temp = Number(value);
        break;
    case 'humidity':
        entry.humidity = Number(value);
        break;
    case 'mq2/raw':
        entry.mq2raw = Number(value);
        break;
    case 'mq2/voltage':
        entry.mq2voltage = Number(value);
        break;
    case 'flame':
        entry.flame = value === '1' || value === 'true' || value === true;
        break;
    case 'gps/status':
        entry.gpsStatus = value;
        break;
    case 'gps/latitude':
        entry.latitude = Number(value);
        break;
    case 'gps/longitude':
        entry.longitude = Number(value);
        break;
    default:
        break;
}
entry.updated = new Date().toISOString();
state[device] = entry;
flow.set('deviceState', state);
return null;

const state = flow.get('deviceState') || {};
const devices = Object.values(state)
    .map(d => ({
        deviceId: d.device,
        temp: d.temp,
        humidity: d.humidity,
        mq2raw: d.mq2raw,
        mq2voltage: d.mq2voltage,
        flame: d.flame,
        gps: {
            status: d.gpsStatus,
            latitude: d.latitude,
            longitude: d.longitude
        },
        updated: d.updated
    }))
    .sort((a, b) => (b.mq2raw ?? -Infinity) - (a.mq2raw ?? -Infinity));
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
msg.payload = { devices };
return msg;

const { deviceId } = msg.req.params;
const state = flow.get('deviceState') || {};
const d = state[deviceId];
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
if (!d) {
    msg.statusCode = 404;
    msg.payload = { error: `Device ${deviceId} not found` };
    return msg;
}
msg.payload = {
    deviceId: d.device,
    temp: d.temp,
    humidity: d.humidity,
    mq2raw: d.mq2raw,
    mq2voltage: d.mq2voltage,
    flame: d.flame,
    gps: {
        status: d.gpsStatus,
        latitude: d.latitude,
        longitude: d.longitude
    },
    updated: d.updated
};
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type'
};
msg.statusCode = 204;
msg.payload = '';
return msg;
